import { writeFileSync } from 'node:fs';
import {
  assetRules,
  documentCacheHeaders,
  securityHeaders,
} from '../lib/http-policy.ts';

const entries = (headers) =>
  Object.entries(headers).map(([key, value]) => ({ key, value }));
const rules = [
  { path: '/*', headers: securityHeaders },
  { path: '/', headers: documentCacheHeaders },
  { path: '/superfocus', headers: documentCacheHeaders },
  { path: '/superfocus/', headers: documentCacheHeaders },
  ...assetRules,
];
writeFileSync(
  'public/_headers',
  '# Generated by scripts/generate-http-config.mjs; edit lib/http-policy.ts.\n' +
    rules
      .map(
        ({ path, headers }) =>
          `${path}\n${entries(headers)
            .map(({ key, value }) => `  ${key}: ${value}`)
            .join('\n')}`,
      )
      .join('\n') +
    '\n',
);
// Hosting rules only. This checkout's active build target remains Cloudflare Workers.
// The response's nonce-based CSP is generated by middleware, never fixed in JSON.
writeFileSync(
  'vercel.json',
  JSON.stringify(
    {
      $schema: 'https://openapi.vercel.sh/vercel.json',
      headers: rules.map(({ path, headers }) => ({
        source: path === '/*' ? '/:path*' : path.replace('/*', '/:path*'),
        headers: entries(headers),
      })),
    },
    null,
    2,
  ) + '\n',
);
console.log('Generated matching Cloudflare and Vercel security/cache rules.');
